   158→/// A structured training workout.
   159→#[derive(Debug, Clone, Serialize, Deserialize)]
   160→pub struct Workout {
   161→    /// Unique identifier
   162→    pub id: Uuid,
   163→    /// Workout name
   164→    pub name: String,
   165→    /// Optional description
   166→    pub description: Option<String>,
   167→    /// Workout creator/author
   168→    pub author: Option<String>,
   169→    /// Original import file path
   170→    pub source_file: Option<String>,
   171→    /// Original file format
   172→    pub source_format: Option<WorkoutFormat>,
   173→    /// Ordered list of segments
   174→    pub segments: Vec<WorkoutSegment>,
   175→    /// Total workout duration in seconds (calculated)
   176→    pub total_duration_seconds: u32,
   177→    /// Estimated Training Stress Score
   178→    pub estimated_tss: Option<f32>,
   179→    /// Estimated Intensity Factor
   180→    pub estimated_if: Option<f32>,
   181→    /// User-defined tags
   182→    pub tags: Vec<String>,
   183→    /// Import/creation timestamp
   184→    pub created_at: DateTime<Utc>,
   185→}
   186→
   187→impl Workout {
   188→    /// Create a new workout with the given name and segments.
   189→    pub fn new(name: String, segments: Vec<WorkoutSegment>) -> Self {
   190→        let total_duration_seconds = segments.iter().map(|s| s.duration_seconds).sum();
   191→
   192→        Self {
   193→            id: Uuid::new_v4(),
   194→            name,
   195→            description: None,
   196→            author: None,
   197→            source_file: None,
   198→            source_format: None,
   199→            segments,
   200→            total_duration_seconds,
   201→            estimated_tss: None,
   202→            estimated_if: None,
   203→            tags: Vec::new(),
   204→            created_at: Utc::now(),
   205→        }
   206→    }
   207→
   208→    /// Calculate estimated TSS and IF for a given FTP.
   209→    pub fn calculate_estimates(&mut self, ftp: u16) {
   210→        if self.segments.is_empty() || ftp == 0 {
   211→            return;
   212→        }
   213→
   214→        // Calculate weighted average intensity
   215→        let mut total_weighted_power = 0.0f64;
   216→        let mut total_duration = 0u32;
   217→
   218→        for segment in &self.segments {
   219→            let duration = segment.duration_seconds;
   220→            let avg_power = match &segment.power_target {
   221→                PowerTarget::Absolute { watts } => *watts as f64,
   222→                PowerTarget::PercentFtp { percent } => ftp as f64 * *percent as f64 / 100.0,
   223→                PowerTarget::Range { start, end } => {
   224→                    let start_watts = start.to_watts(ftp) as f64;
   225→                    let end_watts = end.to_watts(ftp) as f64;
   226→                    (start_watts + end_watts) / 2.0
   227→                }
   228→            };
   229→
   230→            total_weighted_power += avg_power * duration as f64;
   231→            total_duration += duration;
   232→        }
   233→
   234→        if total_duration > 0 {
   235→            let avg_power = total_weighted_power / total_duration as f64;
   236→            let intensity_factor = (avg_power / ftp as f64) as f32;
   237→            let duration_hours = total_duration as f32 / 3600.0;
   238→            let tss = duration_hours * intensity_factor * intensity_factor * 100.0;
   239→
   240→            self.estimated_if = Some(intensity_factor);
   241→            self.estimated_tss = Some(tss);
   242→        }
   243→    }
   244→}
