    23→/// Convert a power target to ZWO decimal format (0.75 = 75% FTP).
    24→///
    25→/// For Absolute power targets, we convert to FTP percentage assuming 100% FTP = 200W
    26→/// as a reasonable default since we don't have the user's FTP available.
    27→fn power_to_decimal(power: &PowerTarget) -> f32 {
    28→    match power {
    29→        PowerTarget::PercentFtp { percent } => *percent as f32 / 100.0,
    30→        PowerTarget::Absolute { watts } => {
    31→            // Convert absolute watts to percentage assuming 200W FTP as default
    32→            // This is a reasonable default for export purposes
    33→            (*watts as f32 / 200.0).min(3.0)
    34→        }
    35→        PowerTarget::Range { start, .. } => power_to_decimal(start),
    36→    }
    37→}
    38→
    39→/// Convert a WorkoutSegment to a ZWO XML element string.
    40→///
    41→/// Handles all segment types:
    42→/// - Warmup: Exported with PowerLow/PowerHigh for ranges, or Power for constant
    43→/// - Cooldown: Exported with PowerLow/PowerHigh for ranges, or Power for constant
    44→/// - SteadyState: Exported with Power attribute
    45→/// - Intervals: Exported as SteadyState elements (intervals are expanded during parsing)
    46→/// - FreeRide: Exported as FreeRide element
    47→/// - Ramp: Exported as Ramp element with PowerLow/PowerHigh
    48→///
    49→/// Duration is always included in seconds.
    50→/// Cadence attributes are included when cadence_target is present.
    51→fn segment_to_xml(segment: &WorkoutSegment) -> String {
    52→    let duration = segment.duration_seconds;
    53→
    54→    // Build cadence attributes if present
    55→    let cadence_attrs = if let Some(ref cadence) = segment.cadence_target {
    56→        if cadence.min_rpm == cadence.max_rpm {
    57→            // Single cadence value
    58→            format!(" Cadence=\"{}\"", cadence.min_rpm)
    59→        } else {
    60→            // Cadence range
    61→            format!(" CadenceLow=\"{}\" CadenceHigh=\"{}\"", cadence.min_rpm, cadence.max_rpm)
    62→        }
    63→    } else {
    64→        String::new()
    65→    };
    66→
    67→    match segment.segment_type {
    68→        SegmentType::Warmup => {
    69→            match &segment.power_target {
    70→                PowerTarget::Range { start, end } => {
    71→                    let low = power_to_decimal(start);
    72→                    let high = power_to_decimal(end);
    73→                    format!(
    74→                        "<Warmup Duration=\"{}\" PowerLow=\"{:.2}\" PowerHigh=\"{:.2}\"{}/>\n",
    75→                        duration, low, high, cadence_attrs
    76→                    )
    77→                }
    78→                _ => {
    79→                    let power = power_to_decimal(&segment.power_target);
    80→                    format!(
    81→                        "<Warmup Duration=\"{}\" Power=\"{:.2}\"{}/>\n",
    82→                        duration, power, cadence_attrs
    83→                    )
    84→                }
    85→            }
    86→        }
    87→        SegmentType::Cooldown => {
    88→            match &segment.power_target {
    89→                PowerTarget::Range { start, end } => {
    90→                    let low = power_to_decimal(start);
    91→                    let high = power_to_decimal(end);
    92→                    format!(
    93→                        "<Cooldown Duration=\"{}\" PowerLow=\"{:.2}\" PowerHigh=\"{:.2}\"{}/>\n",
    94→                        duration, low, high, cadence_attrs
    95→                    )
    96→                }
    97→                _ => {
    98→                    let power = power_to_decimal(&segment.power_target);
    99→                    format!(
   100→                        "<Cooldown Duration=\"{}\" Power=\"{:.2}\"{}/>\n",
   101→                        duration, power, cadence_attrs
   102→                    )
   103→                }
   104→            }
   105→        }
   106→        SegmentType::SteadyState => {
   107→            let power = power_to_decimal(&segment.power_target);
   108→            format!(
   109→                "<SteadyState Duration=\"{}\" Power=\"{:.2}\"{}/>\n",
   110→                duration, power, cadence_attrs
   111→            )
   112→        }
   113→        SegmentType::Intervals => {
   114→            // Intervals are expanded during parsing, so we export each as SteadyState
   115→            let power = power_to_decimal(&segment.power_target);
   116→            format!(
   117→                "<SteadyState Duration=\"{}\" Power=\"{:.2}\"{}/>\n",
   118→                duration, power, cadence_attrs
   119→            )
   120→        }
   121→        SegmentType::FreeRide => {
   122→            format!(
   123→                "<FreeRide Duration=\"{}\"{}/>\n",
   124→                duration, cadence_attrs
   125→            )
   126→        }
   127→        SegmentType::Ramp => {
   128→            match &segment.power_target {
   129→                PowerTarget::Range { start, end } => {
   130→                    let low = power_to_decimal(start);
   131→                    let high = power_to_decimal(end);
   132→                    format!(
   133→                        "<Ramp Duration=\"{}\" PowerLow=\"{:.2}\" PowerHigh=\"{:.2}\"{}/>\n",
   134→                        duration, low, high, cadence_attrs
   135→                    )
   136→                }
   137→                _ => {
   138→                    // Ramp without range - use same power for both
   139→                    let power = power_to_decimal(&segment.power_target);
   140→                    format!(
   141→                        "<Ramp Duration=\"{}\" PowerLow=\"{:.2}\" PowerHigh=\"{:.2}\"{}/>\n",
   142→                        duration, power, power, cadence_attrs
   143→                    )
   144→                }
   145→            }
   146→        }
   147→    }
   148→}
