    14→pub fn export_zwo(workout: &Workout) -> Result<String, WorkoutExportError> {
    15→    if workout.segments.is_empty() {
    16→        return Err(WorkoutExportError::EmptyWorkout);
    17→    }
    18→
    19→    let mut xml = String::new();
    20→
    21→    // XML declaration
    22→    xml.push_str("<?xml version=\"1.0\"?>\n");
    23→
    24→    // Root element
    25→    xml.push_str("<workout_file>\n");
    26→
    27→    // Metadata elements
    28→    xml.push_str(&format!("    <name>{}</name>\n", escape_xml(&workout.name)));
    29→
    30→    if let Some(ref author) = workout.author {
    31→        xml.push_str(&format!("    <author>{}</author>\n", escape_xml(author)));
    32→    }
    33→
    34→    if let Some(ref description) = workout.description {
    35→        xml.push_str(&format!(
    36→            "    <description>{}</description>\n",
    37→            escape_xml(description)
    38→        ));
    39→    }
    40→
    41→    // Tags
    42→    for tag in &workout.tags {
    43→        xml.push_str(&format!("    <tag name=\"{}\"/>\n", escape_xml_attr(tag)));
    44→    }
    45→
    46→    // Workout element with segments
    47→    xml.push_str("    <workout>\n");
    48→    for segment in &workout.segments {
    49→        // Indent segment XML
    50→        let segment_xml = segment_to_xml(segment);
    51→        xml.push_str(&format!("        {}", segment_xml));
    52→    }
    53→    xml.push_str("    </workout>\n");
    54→
    55→    // Close root element
    56→    xml.push_str("</workout_file>\n");
    57→
    58→    Ok(xml)
    59→}
    60→
    61→/// Escape special XML characters in text content.
    62→fn escape_xml(s: &str) -> String {
    63→    s.replace('&', "&amp;")
    64→        .replace('<', "&lt;")
    65→        .replace('>', "&gt;")
    66→}
    67→
    68→/// Escape special XML characters in attribute values.
    69→fn escape_xml_attr(s: &str) -> String {
    70→    s.replace('&', "&amp;")
    71→        .replace('<', "&lt;")
    72→        .replace('>', "&gt;")
    73→        .replace('"', "&quot;")
    74→}
    75→
    76→/// Convert a power target to ZWO decimal format (0.75 = 75% FTP).
    77→///
    78→/// For Absolute power targets, we convert to FTP percentage assuming 100% FTP = 200W
    79→/// as a reasonable default since we don't have the user's FTP available.
    80→fn power_to_decimal(power: &PowerTarget) -> f32 {
    81→    match power {
    82→        PowerTarget::PercentFtp { percent } => *percent as f32 / 100.0,
    83→        PowerTarget::Absolute { watts } => {
    84→            // Convert absolute watts to percentage assuming 200W FTP as default
    85→            // This is a reasonable default for export purposes
    86→            (*watts as f32 / 200.0).min(3.0)
    87→        }
    88→        PowerTarget::Range { start, .. } => power_to_decimal(start),
    89→    }
    90→}
    91→
    92→/// Convert a WorkoutSegment to a ZWO XML element string.
    93→///
    94→/// Handles all segment types:
    95→/// - Warmup: Exported with PowerLow/PowerHigh for ranges, or Power for constant
    96→/// - Cooldown: Exported with PowerLow/PowerHigh for ranges, or Power for constant
    97→/// - SteadyState: Exported with Power attribute
    98→/// - Intervals: Exported as SteadyState elements (intervals are expanded during parsing)
    99→/// - FreeRide: Exported as FreeRide element
   100→/// - Ramp: Exported as Ramp element with PowerLow/PowerHigh
   101→///
   102→/// Duration is always included in seconds.
   103→/// Cadence attributes are included when cadence_target is present.
   104→fn segment_to_xml(segment: &WorkoutSegment) -> String {
   105→    let duration = segment.duration_seconds;
   106→
   107→    // Build cadence attributes if present
   108→    let cadence_attrs = if let Some(ref cadence) = segment.cadence_target {
