    92→/// Convert a WorkoutSegment to a ZWO XML element string.
    93→///
    94→/// Handles all segment types:
    95→/// - Warmup: Exported with PowerLow/PowerHigh for ranges, or Power for constant
    96→/// - Cooldown: Exported with PowerLow/PowerHigh for ranges, or Power for constant
    97→/// - SteadyState: Exported with Power attribute
    98→/// - Intervals: Exported as SteadyState elements (intervals are expanded during parsing)
    99→/// - FreeRide: Exported as FreeRide element
   100→/// - Ramp: Exported as Ramp element with PowerLow/PowerHigh
   101→///
   102→/// Duration is always included in seconds.
   103→/// Cadence attributes are included when cadence_target is present.
   104→fn segment_to_xml(segment: &WorkoutSegment) -> String {
   105→    let duration = segment.duration_seconds;
   106→
   107→    // Build cadence attributes if present
   108→    let cadence_attrs = if let Some(ref cadence) = segment.cadence_target {
   109→        if cadence.min_rpm == cadence.max_rpm {
   110→            // Single cadence value
   111→            format!(" Cadence=\"{}\"", cadence.min_rpm)
   112→        } else {
   113→            // Cadence range
   114→            format!(" CadenceLow=\"{}\" CadenceHigh=\"{}\"", cadence.min_rpm, cadence.max_rpm)
   115→        }
   116→    } else {
   117→        String::new()
   118→    };
   119→
   120→    match segment.segment_type {
   121→        SegmentType::Warmup => {
   122→            match &segment.power_target {
   123→                PowerTarget::Range { start, end } => {
   124→                    let low = power_to_decimal(start);
   125→                    let high = power_to_decimal(end);
   126→                    format!(
   127→                        "<Warmup Duration=\"{}\" PowerLow=\"{:.2}\" PowerHigh=\"{:.2}\"{}/>\n",
   128→                        duration, low, high, cadence_attrs
   129→                    )
   130→                }
   131→                _ => {
   132→                    let power = power_to_decimal(&segment.power_target);
   133→                    format!(
   134→                        "<Warmup Duration=\"{}\" Power=\"{:.2}\"{}/>\n",
   135→                        duration, power, cadence_attrs
   136→                    )
   137→                }
   138→            }
   139→        }
   140→        SegmentType::Cooldown => {
   141→            match &segment.power_target {
   142→                PowerTarget::Range { start, end } => {
   143→                    let low = power_to_decimal(start);
   144→                    let high = power_to_decimal(end);
   145→                    format!(
   146→                        "<Cooldown Duration=\"{}\" PowerLow=\"{:.2}\" PowerHigh=\"{:.2}\"{}/>\n",
   147→                        duration, low, high, cadence_attrs
   148→                    )
   149→                }
   150→                _ => {
   151→                    let power = power_to_decimal(&segment.power_target);
   152→                    format!(
   153→                        "<Cooldown Duration=\"{}\" Power=\"{:.2}\"{}/>\n",
   154→                        duration, power, cadence_attrs
   155→                    )
   156→                }
   157→            }
   158→        }
   159→        SegmentType::SteadyState => {
   160→            let power = power_to_decimal(&segment.power_target);
   161→            format!(
   162→                "<SteadyState Duration=\"{}\" Power=\"{:.2}\"{}/>\n",
   163→                duration, power, cadence_attrs
   164→            )
   165→        }
   166→        SegmentType::Intervals => {
   167→            // Intervals are expanded during parsing, so we export each as SteadyState
   168→            let power = power_to_decimal(&segment.power_target);
   169→            format!(
   170→                "<SteadyState Duration=\"{}\" Power=\"{:.2}\"{}/>\n",
   171→                duration, power, cadence_attrs
   172→            )
   173→        }
   174→        SegmentType::FreeRide => {
   175→            format!(
   176→                "<FreeRide Duration=\"{}\"{}/>\n",
   177→                duration, cadence_attrs
   178→            )
   179→        }
   180→        SegmentType::Ramp => {
   181→            match &segment.power_target {
   182→                PowerTarget::Range { start, end } => {
   183→                    let low = power_to_decimal(start);
   184→                    let high = power_to_decimal(end);
   185→                    format!(
   186→                        "<Ramp Duration=\"{}\" PowerLow=\"{:.2}\" PowerHigh=\"{:.2}\"{}/>\n",
   187→                        duration, low, high, cadence_attrs
   188→                    )
   189→                }
   190→                _ => {
   191→                    // Ramp without range - use same power for both
   192→                    let power = power_to_decimal(&segment.power_target);
   193→                    format!(
   194→                        "<Ramp Duration=\"{}\" PowerLow=\"{:.2}\" PowerHigh=\"{:.2}\"{}/>\n",
   195→                        duration, power, power, cadence_attrs
   196→                    )
   197→                }
   198→            }
   199→        }
   200→    }
   201→}
