   203→/// Export a workout to ZWO format and write to a file.
   204→///
   205→/// # Errors
   206→/// Returns `WorkoutExportError::IoError` if the file cannot be written.
   207→/// Returns `WorkoutExportError::EmptyWorkout` if the workout has no segments.
   208→pub fn export_zwo_to_file(workout: &Workout, path: &Path) -> Result<(), WorkoutExportError> {
   209→    let content = export_zwo(workout)?;
   210→    std::fs::write(path, content)?;
   211→    Ok(())
   212→}
   213→
   214→/// Generate a default filename for a workout ZWO export.
   215→///
   216→/// The filename is based on the workout name with invalid filesystem
   217→/// characters removed and a `.zwo` extension added.
   218→pub fn generate_zwo_filename(workout: &Workout) -> String {
   219→    let sanitized = sanitize_filename(&workout.name);
   220→    format!("{}.zwo", sanitized)
   221→}
   222→
   223→/// Sanitize a string for use as a filename.
   224→fn sanitize_filename(name: &str) -> String {
   225→    name.chars()
   226→        .map(|c| match c {
   227→            '/' | '\\' | ':' | '*' | '?' | '"' | '<' | '>' | '|' => '_',
   228→            _ => c,
   229→        })
   230→        .collect::<String>()
   231→        .trim()
   232→        .to_string()
   233→}
