    25→            let percent = (*watts as f32 / ftp_value as f32 * 100.0) as u8;
    26→            percent.min(255) // Cap at u8 max
    27→        }
    28→        PowerTarget::Range { start, .. } => power_to_percent(start, ftp),
    29→    }
    30→}
