    32→/// Convert a list of workout segments to MRC COURSE DATA points.
    33→///
    34→/// Each segment is converted to time/power pairs:
    35→/// - SteadyState, FreeRide, Intervals: Two points at the same power (start and end)
    36→/// - Warmup, Cooldown, Ramp with Range: Two points at start and end power
    37→/// - Warmup, Cooldown, Ramp without Range: Two points at the same power
    38→///
    39→/// Time accumulates correctly across segments. Power is expressed as percent FTP.
    40→///
    41→/// # Arguments
    42→/// * `segments` - The workout segments to convert
    43→/// * `ftp` - Optional FTP value for converting absolute power targets (defaults to 200W)
    44→///
    45→/// # Returns
    46→/// A vector of CourseDataPoint tuples (minutes, power_percent)
    47→fn segments_to_course_data(segments: &[WorkoutSegment], ftp: Option<u16>) -> Vec<CourseDataPoint> {
    48→    let mut points = Vec::new();
    49→    let mut current_time_minutes: f32 = 0.0;
    50→
    51→    for segment in segments {
    52→        let duration_minutes = segment.duration_seconds as f32 / 60.0;
    53→
    54→        match segment.segment_type {
    55→            SegmentType::SteadyState | SegmentType::FreeRide | SegmentType::Intervals => {
    56→                // Constant power - two points at the same level
    57→                let power = if segment.segment_type == SegmentType::FreeRide {
    58→                    0 // FreeRide means no ERG target, typically 0 or low power
    59→                } else {
    60→                    power_to_percent(&segment.power_target, ftp)
    61→                };
    62→
    63→                points.push(CourseDataPoint {
    64→                    minutes: current_time_minutes,
    65→                    power_percent: power,
    66→                });
    67→                points.push(CourseDataPoint {
    68→                    minutes: current_time_minutes + duration_minutes,
    69→                    power_percent: power,
    70→                });
    71→            }
    72→            SegmentType::Warmup | SegmentType::Cooldown | SegmentType::Ramp => {
    73→                // Check if power target is a range
    74→                match &segment.power_target {
    75→                    PowerTarget::Range { start, end } => {
    76→                        // Ramp with different start/end power
    77→                        let start_power = power_to_percent(start, ftp);
    78→                        let end_power = power_to_percent(end, ftp);
    79→
    80→                        points.push(CourseDataPoint {
    81→                            minutes: current_time_minutes,
    82→                            power_percent: start_power,
    83→                        });
    84→                        points.push(CourseDataPoint {
    85→                            minutes: current_time_minutes + duration_minutes,
    86→                            power_percent: end_power,
    87→                        });
    88→                    }
    89→                    _ => {
    90→                        // Constant power even though segment type suggests ramp
    91→                        let power = power_to_percent(&segment.power_target, ftp);
    92→                        points.push(CourseDataPoint {
    93→                            minutes: current_time_minutes,
    94→                            power_percent: power,
    95→                        });
    96→                        points.push(CourseDataPoint {
    97→                            minutes: current_time_minutes + duration_minutes,
    98→                            power_percent: power,
    99→                        });
   100→                    }
   101→                }
   102→            }
   103→        }
   104→
   105→        current_time_minutes += duration_minutes;
   106→    }
   107→
   108→    points
   109→}
