   232→/// Parse an MRC file from disk.
   233→pub fn parse_mrc_file(path: &std::path::Path) -> Result<Workout, WorkoutParseError> {
   234→    let content =
   235→        std::fs::read_to_string(path).map_err(|e| WorkoutParseError::IoError(e.to_string()))?;
   236→
   237→    let mut workout = parse_mrc(&content)?;
   238→    workout.source_file = Some(path.display().to_string());
   239→
   240→    Ok(workout)
   241→}
