   118→/// Extract text events from workout segments for the MRC COURSE TEXT section.
   119→///
   120→/// Each segment with a text_event is converted to a TextEventEntry with:
   121→/// - The start time of the segment (in minutes)
   122→/// - The text event message
   123→///
   124→/// Segments without text events are skipped.
   125→///
   126→/// # Arguments
   127→/// * `segments` - The workout segments to extract text events from
   128→///
   129→/// # Returns
   130→/// A vector of TextEventEntry with time and text for each text event
   131→fn extract_text_events(segments: &[WorkoutSegment]) -> Vec<TextEventEntry> {
   132→    let mut events = Vec::new();
   133→    let mut current_time_minutes: f32 = 0.0;
   134→
   135→    for segment in segments {
   136→        // If segment has a text event, add it with the current start time
   137→        if let Some(text) = &segment.text_event {
   138→            events.push(TextEventEntry {
   139→                minutes: current_time_minutes,
   140→                text: text.clone(),
   141→            });
   142→        }
   143→
   144→        // Accumulate time for next segment
   145→        current_time_minutes += segment.duration_seconds as f32 / 60.0;
   146→    }
   147→
   148→    events
   149→}
