     1→//! MRC/ERG workout file parser.
     2→//!
     3→//! T061: Implement .mrc/.erg text parser
     4→//!
     5→//! MRC files are simple text-based workout definitions used by TrainerRoad
     6→//! and other training applications. They define power targets as percentage
     7→//! of FTP over time.
     8→
     9→use crate::workouts::types::{
    10→    PowerTarget, SegmentType, Workout, WorkoutFormat, WorkoutParseError, WorkoutSegment,
    11→};
    12→
    13→/// A point in the MRC course data (time -> power percentage).
    14→#[derive(Debug, Clone)]
    15→struct CoursePoint {
    16→    minutes: f32,
    17→    power_percent: u8,
    18→}
    19→
    20→/// A text event at a specific time.
    21→#[derive(Debug, Clone)]
    22→struct TextEvent {
    23→    minutes: f32,
    24→    text: String,
    25→}
    26→
    27→/// Parse an MRC workout from text content.
    28→pub fn parse_mrc(content: &str) -> Result<Workout, WorkoutParseError> {
    29→    let mut name: Option<String> = None;
    30→    let mut description: Option<String> = None;
    31→    let mut course_points: Vec<CoursePoint> = Vec::new();
    32→    let mut text_events: Vec<TextEvent> = Vec::new();
    33→
    34→    // Track which section we're in
    35→    let mut in_header = false;
    36→    let mut in_course_data = false;
    37→    let mut in_course_text = false;
    38→
    39→    for line in content.lines() {
    40→        let line = line.trim();
    41→
    42→        // Skip empty lines
    43→        if line.is_empty() {
    44→            continue;
    45→        }
    46→
    47→        // Section markers
    48→        match line {
    49→            "[COURSE HEADER]" => {
    50→                in_header = true;
    51→                in_course_data = false;
    52→                in_course_text = false;
    53→                continue;
    54→            }
    55→            "[END COURSE HEADER]" => {
    56→                in_header = false;
    57→                continue;
    58→            }
    59→            "[COURSE DATA]" => {
    60→                in_course_data = true;
    61→                in_header = false;
    62→                in_course_text = false;
    63→                continue;
    64→            }
    65→            "[END COURSE DATA]" => {
    66→                in_course_data = false;
    67→                continue;
    68→            }
    69→            "[COURSE TEXT]" => {
    70→                in_course_text = true;
    71→                in_header = false;
    72→                in_course_data = false;
    73→                continue;
    74→            }
    75→            "[END COURSE TEXT]" => {
    76→                in_course_text = false;
    77→                continue;
    78→            }
    79→            _ => {}
    80→        }
    81→
    82→        // Parse header fields
    83→        if in_header {
    84→            if let Some((key, value)) = parse_header_line(line) {
    85→                match key.to_uppercase().as_str() {
    86→                    "FILE NAME" => name = Some(value),
    87→                    "DESCRIPTION" => description = Some(value),
    88→                    _ => {}
    89→                }
    90→            }
    91→        }
    92→
    93→        // Parse course data (time power pairs)
    94→        if in_course_data {
    95→            if let Some(point) = parse_course_point(line) {
    96→                course_points.push(point);
    97→            }
    98→        }
    99→
   100→        // Parse course text (time "message" pairs)
   101→        if in_course_text {
   102→            if let Some(event) = parse_text_event(line) {
   103→                text_events.push(event);
   104→            }
   105→        }
   106→    }
   107→
   108→    // Validate course data
   109→    if course_points.len() < 2 {
   110→        return Err(WorkoutParseError::EmptyWorkout);
   111→    }
   112→
   113→    // Convert course points to segments
   114→    let segments = build_segments(&course_points, &text_events);
   115→
   116→    if segments.is_empty() {
   117→        return Err(WorkoutParseError::EmptyWorkout);
   118→    }
   119→
   120→    let workout_name = name.unwrap_or_else(|| "Unnamed MRC Workout".to_string());
   121→    let mut workout = Workout::new(workout_name, segments);
   122→    workout.description = description;
   123→    workout.source_format = Some(WorkoutFormat::Mrc);
   124→
   125→    Ok(workout)
   126→}
   127→
   128→/// Parse a header line like "KEY = value".
   129→fn parse_header_line(line: &str) -> Option<(String, String)> {
   130→    let parts: Vec<&str> = line.splitn(2, '=').collect();
   131→    if parts.len() == 2 {
   132→        Some((parts[0].trim().to_string(), parts[1].trim().to_string()))
   133→    } else {
   134→        None
   135→    }
   136→}
   137→
   138→/// Parse a course data point like "5.00    75".
   139→fn parse_course_point(line: &str) -> Option<CoursePoint> {
   140→    let parts: Vec<&str> = line.split_whitespace().collect();
   141→    if parts.len() >= 2 {
   142→        let minutes = parts[0].parse().ok()?;
   143→        let power_percent = parts[1].parse().ok()?;
   144→        Some(CoursePoint {
   145→            minutes,
   146→            power_percent,
   147→        })
   148→    } else {
   149→        None
   150→    }
   151→}
   152→
   153→/// Parse a text event line like `5.00    "Zone 3"`.
   154→fn parse_text_event(line: &str) -> Option<TextEvent> {
   155→    // Find the first whitespace to split time from text
   156→    let parts: Vec<&str> = line.splitn(2, char::is_whitespace).collect();
   157→    if parts.len() >= 2 {
   158→        let minutes: f32 = parts[0].trim().parse().ok()?;
   159→        // Remove quotes from text
   160→        let text = parts[1]
   161→            .trim()
   162→            .trim_start_matches('"')
   163→            .trim_end_matches('"')
   164→            .to_string();
   165→        Some(TextEvent { minutes, text })
   166→    } else {
   167→        None
   168→    }
   169→}
   170→
   171→/// Build workout segments from course points.
   172→fn build_segments(points: &[CoursePoint], text_events: &[TextEvent]) -> Vec<WorkoutSegment> {
   173→    let mut segments = Vec::new();
   174→
   175→    for i in 0..points.len() - 1 {
   176→        let start = &points[i];
   177→        let end = &points[i + 1];
   178→
   179→        let start_seconds = (start.minutes * 60.0) as u32;
   180→        let end_seconds = (end.minutes * 60.0) as u32;
   181→        let duration = end_seconds.saturating_sub(start_seconds);
   182→
   183→        if duration == 0 {
   184→            continue;
   185→        }
   186→
   187→        // Determine segment type and power target
   188→        let (segment_type, power_target) = if start.power_percent == end.power_percent {
   189→            // Constant power - steady state
   190→            (
   191→                SegmentType::SteadyState,
   192→                PowerTarget::percent_ftp(start.power_percent),
   193→            )
   194→        } else if start.power_percent < end.power_percent {
   195→            // Increasing power - warmup or ramp
   196→            (
   197→                SegmentType::Warmup,
   198→                PowerTarget::range(
   199→                    PowerTarget::percent_ftp(start.power_percent),
   200→                    PowerTarget::percent_ftp(end.power_percent),
   201→                ),
   202→            )
   203→        } else {
   204→            // Decreasing power - cooldown
   205→            (
   206→                SegmentType::Cooldown,
   207→                PowerTarget::range(
   208→                    PowerTarget::percent_ftp(start.power_percent),
   209→                    PowerTarget::percent_ftp(end.power_percent),
   210→                ),
   211→            )
   212→        };
   213→
   214→        // Find text event for this segment (at segment start time)
   215→        let text_event = text_events
   216→            .iter()
   217→            .find(|e| (e.minutes - start.minutes).abs() < 0.01)
   218→            .map(|e| e.text.clone());
   219→
   220→        segments.push(WorkoutSegment {
   221→            segment_type,
   222→            duration_seconds: duration,
   223→            power_target,
   224→            cadence_target: None,
   225→            text_event,
   226→        });
   227→    }
   228→
   229→    segments
   230→}
