   159→/// Export a workout to MRC format.
   160→///
   161→/// Returns the workout as an MRC-formatted text string.
   162→///
   163→/// The MRC format consists of:
   164→/// - `[COURSE HEADER]` section with FILE NAME and optional DESCRIPTION
   165→/// - `[COURSE DATA]` section with time/power percentage pairs
   166→/// - `[COURSE TEXT]` section with text events (if any exist)
   167→///
   168→/// # Arguments
   169→/// * `workout` - The workout to export
   170→///
   171→/// # Errors
   172→/// Returns `WorkoutExportError::EmptyWorkout` if the workout has no segments.
   173→///
   174→/// # Example
   175→/// ```ignore
   176→/// let workout = Workout::new("Sweet Spot", segments);
   177→/// let mrc_content = export_mrc(&workout)?;
   178→/// ```
   179→pub fn export_mrc(workout: &Workout) -> Result<String, WorkoutExportError> {
   180→    export_mrc_with_ftp(workout, None)
   181→}
   182→
   183→/// Export a workout to MRC format with a specific FTP value.
   184→///
   185→/// This variant allows specifying an FTP value for converting absolute power
   186→/// targets to percentages. Use this when the workout contains absolute watt targets.
   187→///
   188→/// # Arguments
   189→/// * `workout` - The workout to export
   190→/// * `ftp` - Optional FTP value for converting absolute power targets (defaults to 200W)
   191→///
   192→/// # Errors
   193→/// Returns `WorkoutExportError::EmptyWorkout` if the workout has no segments.
   194→pub fn export_mrc_with_ftp(workout: &Workout, ftp: Option<u16>) -> Result<String, WorkoutExportError> {
   195→    if workout.segments.is_empty() {
   196→        return Err(WorkoutExportError::EmptyWorkout);
   197→    }
   198→
   199→    let mut output = String::new();
   200→
   201→    // Build [COURSE HEADER] section
   202→    output.push_str("[COURSE HEADER]\n");
   203→    output.push_str(&format!("FILE NAME = {}\n", workout.name));
   204→    if let Some(ref desc) = workout.description {
   205→        output.push_str(&format!("DESCRIPTION = {}\n", desc));
   206→    }
   207→    output.push_str("[END COURSE HEADER]\n");
   208→
   209→    // Build [COURSE DATA] section
   210→    output.push_str("[COURSE DATA]\n");
   211→    let course_data = segments_to_course_data(&workout.segments, ftp);
   212→    for point in &course_data {
   213→        output.push_str(&format!("{:.2}\t{}\n", point.minutes, point.power_percent));
   214→    }
   215→    output.push_str("[END COURSE DATA]\n");
   216→
   217→    // Build [COURSE TEXT] section if there are text events
   218→    let text_events = extract_text_events(&workout.segments);
   219→    if !text_events.is_empty() {
   220→        output.push_str("[COURSE TEXT]\n");
   221→        for event in &text_events {
   222→            output.push_str(&format_text_event(event));
   223→            output.push('\n');
   224→        }
   225→        output.push_str("[END COURSE TEXT]\n");
   226→    }
   227→
   228→    Ok(output)
